target.css:
:root {
  --ink: #17364a;
  --paper: #fffdf7;
  --line: #d7e4dc;
  --leaf: #277a5b;
  --mint: #e0f3e8;
  --tomato: #df6b4d;
  --sun: #f5c75d;
}

.drop-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--leaf);
  border-radius: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.produce-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  font-size: 22px;
  background: var(--sun);
  border-radius: 12px;
}

.title-group {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.title-group h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.open-badge {
  padding: 5px 8px;
  color: var(--leaf);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.pickup-slot {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  margin-top: 14px;
  padding: 11px 12px 11px 14px;
  background: var(--mint);
  border-radius: 12px;
}

.time-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
}

.time-copy span {
  font-size: 12px;
}

.time-copy strong {
  font-size: 18px;
  line-height: 1;
}

.date-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 44px;
  padding: 4px 0;
  color: var(--paper);
  background: var(--tomato);
  border-radius: 9px;
  line-height: 1;
}

.date-tile span,
.date-tile small {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.6px;
}

.date-tile strong {
  margin: 2px 0;
  font-size: 20px;
}

.accepted-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  padding: 0;
  margin: 12px 0;
  list-style: none;
}

.accepted-list li {
  padding: 7px 6px;
  text-align: center;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 12px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  font-size: 12px;
}

.card-footer button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--leaf);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

.card-footer button span {
  margin-left: 4px;
  font-size: 15px;
}

